​
    int time = 0;
    int remain = 0;
    for (int i = 0; i < n; i++) {
        int tmp = 0;
        cin >> tmp;
        // 一直让gpu运行，防止空转
        if (tmp + remain > executeCount) {
            remain = tmp + remain - executeCount;
        } else {
            remain = 0;
        }
        time++;
    }
