JAVA:
import java.util.Scanner;
​
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // 每轮 GPU 可执行任务数
        int executeCount = sc.nextInt();
        // 任务数
        int n = sc.nextInt();
​
        int time = 0;
        int remain = 0; // 上一轮未完成任务
        for (int i = 0; i < n; i++) {
            int task = sc.nextInt();
            // 如果当前任务加剩余任务超过执行上限，累加剩余
            if (task + remain > executeCount) {
                remain = task + remain - executeCount;
            } else {
                remain = 0; // 否则任务执行完毕
            }
            time++;
        }
​
        // 继续执行剩余任务
        while (remain > 0) {
            remain -= executeCount;
            time++;
        }
​
        System.out.println(time);
    }
}
