go:
package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取每轮最大执行数
    line1, _ := reader.ReadString('\n')
    executeCount, _ := strconv.Atoi(strings.TrimSpace(line1))
​
    // 读取任务总数
    line2, _ := reader.ReadString('\n')
    n, _ := strconv.Atoi(strings.TrimSpace(line2))
​
    // 读取任务列表
    line3, _ := reader.ReadString('\n')
    taskStrs := strings.Fields(line3)
    tasks := make([]int, n)
    for i := 0; i < n; i++ {
        tasks[i], _ = strconv.Atoi(taskStrs[i])
    }
​
    time := 0
    remain := 0 // 剩余任务
​
    // 遍历每一轮任务
    for _, task := range tasks {
        if task + remain > executeCount {
            remain = task + remain - executeCount
        } else {
            remain = 0
        }
        time++
    }
​
    // 继续执行剩余任务
    for remain > 0 {
        remain -= executeCount
        time++
    }
​
    fmt.Println(time)
}
